            j = (i + 1) % len(sides)
            k = (i + 2) % len(sides)
            area += sides[i] * sides[j] * math.sin(math.acos((sides[i]**2 + sides[j]**2 - sides[k]**2) / (2 * sides[i] * sides[j])))
