import random
import math

def calculate_area(sides):
    n = len(sides)
    if n < 3:
        return 0
    if n == 3:
        a, b, c = sorted(sides)
        s = (a + b + c) / 2
        return math.sqrt(s * (s - a) * (s - b) * (s - c))

    # Use Bretschneider's formula for general quadrilaterals
    def bretschneider_area(a, b, c, d, p, q):
        s = (a + b + c + d) / 2
        return math.sqrt((s - a) * (s - b) * (s - c) * (s - d) - a * b * c * d * math.cos(p) ** 2)

    max_area = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    sides_set = [sides[i], sides[j], sides[k], sides[l]]
                    if sum(sides_set) > 2 * max(sides_set):
                        continue
                    a, b, c, d = sorted(sides_set)
                    p = math.acos((a**2 + b**2 - c**2 - d**2) / (-2 * c * d))
                    q = math.acos((c**2 + d**2 - a**2 - b**2) / (-2 * a * b))
                    area = bretschneider_area(a, b, c, d, p, q)
                    max_area = max(max_area, area)
    return max_area

def simulated_annealing(sides, max_iterations=10000, initial_temp=1000, cooling_rate=0.99):
    n = len(sides)
    current_solution = random.sample(sides, min(n, 4))
    current_area = calculate_area(current_solution)

    for _ in range(max_iterations):
        temp = initial_temp * cooling_rate ** _
        if temp < 1e-6:
            break

        new_solution = current_solution[:]
        idx1, idx2 = random.sample(range(n), 2)
        new_solution[idx1], new_solution[idx2] = new_solution[idx2], new_solution[idx1]

        new_area = calculate_area(new_solution)

        if new_area > current_area or random.random() < math.exp((new_area - current_area) / temp):
            current_solution = new_solution
            current_area = new_area

    return current_area

